'use client'
import { cn } from '@cascivo/core'
import { forwardRef } from 'react'
import type { InputHTMLAttributes, ReactNode } from 'react'
import styles from './checkbox-card.module.css'

export interface CheckboxCardProps extends Omit<
  InputHTMLAttributes<HTMLInputElement>,
  'title' | 'onChange'
> {
  title: ReactNode
  description?: ReactNode
  onCheckedChange?: (checked: boolean) => void
  className?: string | undefined
}

/**
 * `forwardRef` so `ref` reaches the underlying `<input>` — and so it is TYPED. See
 * `textarea.tsx` for the full rationale (2026-07-28 report C10). Enforced by
 * `ref-parity.test.ts`, which found this component: the plan's own list of 16 was itself
 * incomplete, which is why the rule is a guard and not a checklist.
 */
export const CheckboxCard = forwardRef<HTMLInputElement, CheckboxCardProps>(function CheckboxCard(
  { title, description, checked, defaultChecked, disabled, onCheckedChange, className, ...props },
  ref,
) {
  return (
    <label className={cn(styles['card'], className)} data-disabled={disabled || undefined}>
      <input
        type="checkbox"
        className={styles['input']}
        disabled={disabled}
        {...(checked !== undefined ? { checked } : { defaultChecked })}
        onChange={(e) => onCheckedChange?.(e.currentTarget.checked)}
        ref={ref as never}
        {...props}
      />
      <span className={styles['glyph']} aria-hidden="true">
        <svg viewBox="0 0 12 12" className={styles['check']}>
          <path d="M2.5 6.5 5 9l4.5-5.5" fill="none" stroke="currentColor" strokeWidth="1.5" />
        </svg>
      </span>
      <span className={styles['body']}>
        <span className={styles['title']}>{title}</span>
        {description && <span className={styles['description']}>{description}</span>}
      </span>
    </label>
  )
})

@layer cascivo.component {
  .card {
    display: flex;
    gap: var(--cascivo-space-3);
    align-items: flex-start;
    padding: var(--cascivo-space-4);
    border: 1px solid var(--cascivo-color-border);
    border-radius: var(--cascivo-radius-surface);
    background: var(--cascivo-color-bg);
    cursor: pointer;
    transition:
      border-color var(--cascivo-duration-100) ease,
      background-color var(--cascivo-duration-100) ease;
  }

  .card:hover:not([data-disabled]) {
    border-color: var(--cascivo-color-border-strong);
  }

  .card:has(input:checked) {
    border-color: var(--cascivo-color-accent);
    background: color-mix(in oklch, var(--cascivo-color-accent) 4%, var(--cascivo-color-bg));
  }

  .card:has(input:focus-visible) {
    box-shadow: var(--cascivo-focus-ring);
  }

  .card[data-disabled] {
    opacity: 0.5;
    cursor: not-allowed;
  }

  .input {
    position: absolute;
    inline-size: 1px;
    block-size: 1px;
    overflow: hidden;
    clip-path: inset(50%);
    white-space: nowrap;
  }

  .glyph {
    flex: none;
    inline-size: 1rem;
    block-size: 1rem;
    margin-block-start: 2px;
    display: grid;
    place-items: center;
    border: 1px solid var(--cascivo-color-border-strong);
    border-radius: var(--cascivo-radius-indicator);
    color: transparent;
    transition: all var(--cascivo-duration-100) ease;
  }

  .card:has(input:checked) .glyph {
    border-color: var(--cascivo-color-accent);
    background: var(--cascivo-color-accent);
    color: var(--cascivo-color-accent-foreground, oklch(1 0 0));
  }

  .check {
    inline-size: 0.75rem;
    block-size: 0.75rem;
  }

  .body {
    display: flex;
    flex-direction: column;
    gap: var(--cascivo-space-1);
  }

  .title {
    font-size: var(--cascivo-text-sm);
    font-weight: var(--cascivo-font-medium);
    color: var(--cascivo-color-text);
  }

  .description {
    font-size: var(--cascivo-text-sm);
    color: var(--cascivo-color-text-subtle);
  }
}

import type { ComponentMeta } from '@cascivo/core'

export const meta: ComponentMeta = {
  name: 'CheckboxCard',
  description:
    'Multi-selectable card backed by a native checkbox. Use multiple independent CheckboxCards for multi-select scenarios.',
  category: 'inputs',
  // Backed by a native checkbox, so selection works and submits without JS.
  clientJs: 'enhancement',
  states: ['default', 'checked', 'disabled'],
  variants: [],
  sizes: [],
  props: [
    { name: 'title', type: 'ReactNode', required: true, description: 'Card title' },
    {
      name: 'description',
      type: 'ReactNode',
      required: false,
      description: 'Optional description',
    },
    { name: 'checked', type: 'boolean', required: false, description: 'Controlled checked state' },
    {
      name: 'defaultChecked',
      type: 'boolean',
      required: false,
      description: 'Uncontrolled default',
    },
    {
      name: 'onCheckedChange',
      type: '(checked: boolean) => void',
      required: false,
      description: 'Change callback',
    },
    { name: 'disabled', type: 'boolean', required: false, description: 'Disables the card' },
  ],
  tokens: ['--cascivo-color-accent', '--cascivo-color-border', '--cascivo-radius-surface'],
  accessibility: {
    role: 'checkbox',
    wcag: '2.2-AA',
    keyboard: ['Space'],
  },
  examples: [
    {
      title: 'Feature toggles',
      code: `<div style={{ display: 'grid', gap: 12 }}>
  <CheckboxCard title="Automated backups" description="Daily snapshots, 30-day retention" defaultChecked />
  <CheckboxCard title="Monitoring" description="Metrics + alerting" />
  <CheckboxCard title="Audit log" description="Requires Team plan" disabled />
</div>`,
      description: 'Multi-select feature toggles',
    },
  ],
  dependencies: ['@cascivo/core'],
  tags: ['checkbox', 'card', 'selectable', 'form'],
  intent: {
    whenToUse: [
      'Multi-select where each option needs a title and supporting description (feature toggles, add-ons)',
      'Presenting selectable options as larger, scannable click targets rather than a dense checkbox list',
    ],
    whenNotToUse: [
      'A simple labelled boolean in a form — use Checkbox',
      'Choosing exactly one option from a set — use RadioCard or Radio',
    ],
    antiPatterns: [
      {
        bad: 'Using CheckboxCard for mutually exclusive options',
        good: 'Use RadioCard so only one can be selected',
        why: 'Each CheckboxCard is an independent native checkbox — nothing enforces a single selection across them',
      },
      {
        bad: 'Cramming a paragraph of marketing copy into description',
        why: 'The description is a single supporting line; long content breaks the card layout and scannability',
      },
    ],
    related: [
      {
        name: 'Checkbox',
        relationship: 'alternative',
        reason: 'Use the plain checkbox when a title/description card is overkill',
      },
      {
        name: 'RadioCard',
        relationship: 'alternative',
        reason: 'Use for single-select card groups',
      },
    ],
    a11yRationale:
      'Backed by a native <input type="checkbox"> inside a <label>, so the entire card is clickable and role, checked state, Space activation, and label association come from the platform; the SVG glyph is aria-hidden as it is purely decorative',
    content: {
      tone: 'Title is a concise noun phrase; description is one supporting line',
      notes: 'Keep description to a single line of context (what it does, plan requirements)',
    },
    flexibility: [
      {
        area: 'controlled vs uncontrolled',
        level: 'flexible',
        note: 'Supports both checked + onCheckedChange and defaultChecked',
      },
      {
        area: 'token names',
        level: 'strict',
        note: 'Card styling resolves to --cascivo-color-accent / --cascivo-color-border / --cascivo-radius-surface',
      },
    ],
  },
}
